import{_ as o,l as s,o as t,c as l,v as e,p as n,x as i,d as p,i as f,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"薄透镜成像方程","description":"","frontmatter":{"title":"薄透镜成像方程","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/thin-lens-equation.md","filePath":"litho/thin-lens-equation.md","lastUpdated":1789023840000}'),c={name:"litho/thin-lens-equation.md"};function d(m,a,E,_,u,B){const r=s("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="薄透镜成像方程" tabindex="-1">薄透镜成像方程 <a class="header-anchor" href="#薄透镜成像方程" aria-label="Permalink to &quot;薄透镜成像方程&quot;">​</a></h1><div class="epigraph"><p>近轴极限下，薄透镜把物距、像距与焦距收成一条倒数关系；物在焦点外则成实像，不必先写衍射积分。</p><footer>—— 据 Hecht, Optics 与 Born &amp; Wolf, Principles of Optics 对 paraxial 成像的整理</footer></div><p><a href="/litho/thin-film-interference">上一课</a>处理膜层里的多束干涉。本课换一套语言：物点、像点与透镜焦距。不重推菲涅尔系数。缺口是：投影系统「把掩模平面搬到晶圆平面」在 paraxial 极限下写成什么方程？后课放大率、光瞳与像差，都从这式子出发。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前六课在波动框架里走完界面与薄膜。光刻机工程图却画光轴、物面、像面、焦点。若不会</p> \\[\\frac{1}{s}+\\frac{1}{s&#39;}=\\frac{1}{f}, \\]<p>无法把「共轭距离」与透镜功率对应，也无法理解缩小投影为何物方比像方长。缺口是几何光学的零阶模型，不是再问薄膜反射率。</p><p>波动仍在：几何像点是亥姆霍兹方程短波极限下的汇聚。本课先用这极限把共轭钉死；何时必须回到衍射，见 <a href="/litho/scalar-diffraction-bound">标量衍射的适用边界</a>。</p><p><span class="marginnote">符号约定各国教材对 \\(s\\)、\\(s&#39;\\) 的正负有时相反。本课用「实物在左为正、实像在右为正」。读 Hecht 与 Born &amp; Wolf 时以各自前言为准，公式形状相同。</span></p><h3 id="薄透镜不是光刻物镜的零件清单" tabindex="-1">薄透镜不是光刻物镜的零件清单 <a class="header-anchor" href="#薄透镜不是光刻物镜的零件清单" aria-label="Permalink to &quot;薄透镜不是光刻物镜的零件清单&quot;">​</a></h3><p>「薄」指厚度趋于零、折射可收在一个平面上；真实投影物镜是厚透镜组、多片、有光阑。工程师仍先用薄透镜方程定共轭，再把组代成等效焦距。本课方程是零阶，不是机台剖视图。</p><p><span class="marginnote">符号：物在左、实像在右时 \\(s\\gt 0\\)、\\(s&#39;\\gt 0\\)；会聚透镜 \\(f\\gt 0\\)。paraxial 指 \\(\\sin\\theta\\approx\\theta\\)。功率 \\(\\Phi=1/f\\)，单位屈光度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>高斯成像方程如上。\\(s\\gt f\\) 得实像；\\(s=2f\\) 时 \\(s&#39;=2f\\)，横向等大。\\(s\\to f^+\\) 则 \\(s&#39;\\to\\infty\\)；\\(s\\to\\infty\\) 则 \\(s&#39;\\to f\\)，平行光会聚于后焦面。多片组合用矩阵光学或等效 \\(f\\)；光刻投影物镜是有限共轭的厚系统，瞬时仍满足物像共轭。横向放大率 \\(M=-s&#39;/s\\) 下一课展开，本课只先承认像高随 \\(s&#39;\\)、\\(s\\) 变。</p><p>符号约定必须前后一致：物距从物到透镜（或主面），像距从透镜到像。若把晶圆到末片的空气间隙误当成 \\(s&#39;\\)，共轭会算错一整段。本课方程不管透镜有多厚，只问等效 \\(f\\) 与两个主面距离。真实排光路时再把主面位置从镜头图纸读出。</p>',15)),(t(),n(h,null,{default:i(()=>[f(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E7%89%A9%E7%82%B9%22%5D%20--%3E%20LENS%5B%22%E8%96%84%E9%80%8F%E9%95%9C%E7%84%A6%E8%B7%9D%20f%22%5D%0A%20%20LENS%20--%3E%20IMG%5B%22%E5%83%8F%E7%82%B9%22%5D%0A%20%20OBJ%20--%3E%20EQ%5B%221%2Fs%20%2B%201%2Fs'%20%3D%201%2Ff%22%5D%0A%20%20IMG%20--%3E%20EQ%0A%20%20EQ%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%94%BE%E5%A4%A7%E7%8E%87%20M%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>近轴折射定律连乘之后，同一物点发出的近轴光线重新交于一点——这就是「成像」。投影光刻把掩模放在物方、晶圆放在像方；缩小意味着像距相对物距更短。扫描仪让掩模与晶圆同步扫描，每一瞬间仍满足共轭；运动控制不是本课。</p><p>焦距由曲率与折射率决定（磨镜者公式）。浸没把像方介质 \\(n\\) 从 1 抬高，等效功率与后课 NA 一起变；本课先把 \\(f\\) 当给定参数。色差使 \\(f=f(\\lambda)\\)，带宽课再处理；本课单色。</p><p>厚透镜要用主面：物距、像距从主面量起，而不是从玻璃物理表面。薄透镜把两主面收成同一平面，所以方程里只有一个 \\(f\\)。投影物镜一定是厚的，但共轭关系仍写成对等效 \\(f\\) 的同一条倒数式。这就是「零阶还够用来排距离」的含义。扫描曝光每一瞬时场仍满足该共轭；扫描并不改写成像方程，只是换哪一块视场正在共轭。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课忽略像差、有限孔径衍射与视场光阑。边缘光线不满足 paraxial，像点糊成斑——<a href="/litho/geometric-aberration-tour">几何像差一览</a>。像方远心（主光线近似垂直晶圆）是光刻物镜的常见约束，本课不推导，只在光瞳课点名。</p><p>虚像（\\(s\\lt f\\)）在显微镜物镜一侧常见，投影光刻要的是实像落在晶圆上，本课默认 \\(s\\gt f\\)。后课默认：物像共轭满足薄透镜方程（或等效焦距的同一形式）；实像、倒像、有限共轭是投影的零阶图。下一课 <a href="/litho/focal-magnification">焦距、物距与横向放大</a> 只补 \\(M\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>薄透镜：\\(\\frac{1}{s}+\\frac{1}{s&#39;}=\\frac{1}{f}\\)；实像要求 \\(s\\gt f\\)。</li><li>投影把掩模与晶圆放在共轭两侧；方程是零阶，真实物镜是厚透镜组。</li><li>放大率下一课才写；像差与衍射是更后的修正。</li><li>几何光学是短波极限，不取代本栏开头的波动方程。</li><li>出处：Hecht, <em>Optics</em>；Born &amp; Wolf, <em>Principles of Optics</em> 第 4 章。</li></ul>',9))])}const q=o(c,[["render",d]]);export{b as __pageData,q as default};
